import staticText from "./static-text.txt" with { type: "text" };
import staticJson from "./static-json.json" with { type: "json" };
import staticBytes from "./static-bytes.bin" with { type: "bytes" };

export const staticValues = {
  staticText: staticText.trim(),
  staticJson: staticJson.value,
  staticBytes: new TextDecoder().decode(staticBytes).trim(),
};
